package com.robisa693.exactstacks;

import java.util.ArrayList;
import java.util.List;

public class DenominationFormatter
{
    private static final long MILLION = 1_000_000L;
    private static final long THOUSAND = 1_000L;

    // Game display tiers: exact below 100K, "xK" from 100K, "xM" from 10M
    private static final long K_DISPLAY_THRESHOLD = 100 * THOUSAND;
    private static final long M_DISPLAY_THRESHOLD = 10 * MILLION;

    /**
     * Returns the denomination lines the game's rounded stack display hides.
     * The game shows the exact quantity below 100K (nothing to add),
     * thousands ("5250K") from 100K (only the sub-K units are hidden),
     * and millions ("39M") from 10M (the K and sub-K remainder is hidden).
     */
    public static List<String> remainderLines(long quantity)
    {
        List<String> parts = new ArrayList<>(2);
        if (quantity < K_DISPLAY_THRESHOLD)
        {
            return parts;
        }

        if (quantity >= M_DISPLAY_THRESHOLD)
        {
            long k = (quantity % MILLION) / THOUSAND;
            if (k > 0)
            {
                parts.add(k + "K");
            }
        }

        long units = quantity % THOUSAND;
        if (units > 0)
        {
            parts.add(String.valueOf(units));
        }

        return parts;
    }
}

package com.robisa693.exactstacks;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("exactstacks")
public interface StackBreakdownConfig extends Config
{
    @ConfigItem(
        keyName = "showInventory",
        name = "Show in inventory",
        description = "Show breakdown on items in your inventory."
    )
    default boolean showInventory()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showBank",
        name = "Show in bank",
        description = "Show breakdown on items in the bank grid."
    )
    default boolean showBank()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showLessThanK",
        name = "Show individual units",
        description = "Show amounts less than 1K (e.g. 640gp). Uncheck to show only K values."
    )
    default boolean showLessThanK()
    {
        return true;
    }

    @ConfigItem(
        keyName = "hideMaxStack",
        name = "Hide max stack sentinel",
        description = "Fix for inventory setups compatibility."
    )
    default boolean hideMaxStack()
    {
        return true;
    }
}

package com.robisa693.exactstacks;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;

import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.TextComponent;

class StackBreakdownOverlay extends WidgetItemOverlay
{
    private final StackBreakdownConfig config;

    StackBreakdownOverlay(StackBreakdownConfig config)
    {
        this.config = config;
        if (config.showInventory()) showOnInventory();
        if (config.showBank()) showOnBank();
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        if (itemId == -1)
        {
            return;
        }

        long quantity = widgetItem.getQuantity();
        if (config.hideMaxStack() && quantity == Integer.MAX_VALUE)
        {
            return;
        }
        if (quantity < 100_000)
        {
            return;
        }

        List<String> lines = DenominationFormatter.remainderLines(quantity);

        List<String> filtered = new ArrayList<>(lines.size());
        for (String line : lines)
        {
            if (!line.endsWith("K") && !config.showLessThanK())
            {
                continue;
            }
            filtered.add(line);
        }
        if (filtered.isEmpty())
        {
            return;
        }

        graphics.setFont(FontManager.getRunescapeSmallFont());

        Rectangle bounds = widgetItem.getCanvasBounds();
        var fontMetrics = graphics.getFontMetrics();
        int lineHeight = fontMetrics.getHeight() - 2;
        int leftEdge = bounds.x;
        int baseline = bounds.y + fontMetrics.getAscent() + 9;

        for (String line : filtered)
        {
            TextComponent text = new TextComponent();
            text.setText(line);
            text.setColor(Color.WHITE);
            text.setPosition(new Point(leftEdge, baseline));
            text.render(graphics);

            baseline += lineHeight;
        }
    }
}

package com.robisa693.exactstacks;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Exact Stacks",
    description = "Shows exact coin stack values broken down by denomination (b/m/k/gp)",
    tags = {"exact", "stacks", "coins", "gp", "value", "quantity", "count", "breakdown", "denominations"}
)
public class StackBreakdownPlugin extends Plugin
{
    @Inject
    private OverlayManager overlayManager;

    @Inject
    private StackBreakdownConfig config;

    private StackBreakdownOverlay overlay;

    @Provides
    StackBreakdownConfig getConfig(ConfigManager configManager)
    {
        return configManager.getConfig(StackBreakdownConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlay = new StackBreakdownOverlay(config);
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!event.getGroup().equals("exactstacks"))
        {
            return;
        }

        if (event.getKey().equals("showInventory") || event.getKey().equals("showBank"))
        {
            overlayManager.remove(overlay);
            overlay = new StackBreakdownOverlay(config);
            overlayManager.add(overlay);
        }
    }
}

package com.robisa693.exactstacks;

import org.junit.Test;
import java.util.Arrays;
import java.util.Collections;
import static org.junit.Assert.assertEquals;

public class DenominationFormatterTest
{
    @Test
    public void testZero()
    {
        assertEquals(Collections.emptyList(), DenominationFormatter.remainderLines(0));
    }

    @Test
    public void testNegative()
    {
        assertEquals(Collections.emptyList(), DenominationFormatter.remainderLines(-1));
    }

    @Test
    public void testBelowKDisplayShowsNothing()
    {
        // Game shows the exact quantity below 100K
        assertEquals(Collections.emptyList(), DenominationFormatter.remainderLines(99_999));
    }

    @Test
    public void testExact100K()
    {
        // Game shows "100K", no remainder
        assertEquals(Collections.emptyList(), DenominationFormatter.remainderLines(100_000));
    }

    @Test
    public void testKDisplayRangeShowsOnlyUnits()
    {
        // Game shows "101K"; only the 123 is hidden
        assertEquals(Arrays.asList("123"), DenominationFormatter.remainderLines(101_123));
    }

    @Test
    public void testMillionsStillInKDisplayRange()
    {
        // Game shows "5250K" — the K part is already visible, only units are hidden
        assertEquals(Arrays.asList("640"), DenominationFormatter.remainderLines(5_250_640));
    }

    @Test
    public void testJustBelowMDisplay()
    {
        // Game shows "9999K"
        assertEquals(Arrays.asList("999"), DenominationFormatter.remainderLines(9_999_999));
    }

    @Test
    public void testExact10M()
    {
        // Game shows "10M", no remainder
        assertEquals(Collections.emptyList(), DenominationFormatter.remainderLines(10_000_000));
    }

    @Test
    public void testMDisplayUnitsOnly()
    {
        assertEquals(Arrays.asList("303"), DenominationFormatter.remainderLines(10_000_303));
    }

    @Test
    public void testMDisplayKAndUnits()
    {
        assertEquals(Arrays.asList("205K", "303"), DenominationFormatter.remainderLines(11_205_303));
    }

    @Test
    public void testMDisplayKOnly()
    {
        assertEquals(Arrays.asList("205K"), DenominationFormatter.remainderLines(11_205_000));
    }

    @Test
    public void testMaxCashStack()
    {
        // Game shows "2147M"
        assertEquals(Arrays.asList("483K", "647"), DenominationFormatter.remainderLines(2_147_483_647));
    }

    @Test
    public void testExactThousandInMRange()
    {
        assertEquals(Arrays.asList("483K"), DenominationFormatter.remainderLines(2_147_483_000));
    }

    @Test
    public void testRoundBillion()
    {
        // Game shows "1000M", no remainder
        assertEquals(Collections.emptyList(), DenominationFormatter.remainderLines(1_000_000_000));
    }
}
